public class RedisLock implements DistributableLock {

    private final RedisConfigManager redisConfigManager;
    private final Redisson redisson;

    public RedisLock(final Redisson redisson) {
        this.redisson = this.redisConfigManager.getRedisson();
    }

    @Override
    public void acquireLock(final Object object) {
        getLockInstance(object).lock(this.redisConfigManager.getLockTimeoutInMillis(), TimeUnit.MILLISECONDS);
    }

    @Override
    public void releaseLock(final Object object) {
        getLockInstance(object).unlock();
    }

    @Override
    public boolean tryWriteLock(final Object object) {
        return getReadWriteLockInstance(object).writeLock().tryLock();
    }

    @Override
    public void acquireReadLock(final Object object) {
        getReadWriteLockInstance(object).readLock().lock();
    }

    @Override
    public void releaseReadLock(final Object object) {
        getReadWriteLockInstance(object).readLock().unlock();
    }

    @Override
    public void acquireWriteLock(final Object object) {
        getReadWriteLockInstance(object).writeLock().lock(this.redisConfigManager.getLockTimeoutInMillis(), TimeUnit.MILLISECONDS);
    }

    @Override
    public void releaseWriteLock(final Object object) {
         getReadWriteLockInstance(object).writeLock().unlock();
    }

    private RLock getLockInstance(final Object object) {
        Assert.notNull(object, "Cannot lock or unlock a null object");

        final RLock rLock = this.redisson.getLock(Integer.toString(object.hashCode()));
        if (rLock == null) {
            throw new IllegalStateException("Cannot get lock instance.");
        }
        return rLock;
    }

    private RReadWriteLock getReadWriteLockInstance(final Object object) {
        Assert.notNull(object, "Cannot lock or unlock a null object");

        final RReadWriteLock rwLock = this.redisson.getReadWriteLock(Integer.toString(object.hashCode()));
        if (rwLock == null) {
            throw new IllegalStateException("Cannot get read write lock instance.");
        }
        return rwLock;
    }

}


